window.ATLAS.addDetails("computing.nodes",{"nodes":{
"relay-logic-gates":{"description":{"zh":"两个开关串联是与、并联是或、常闭是非，真值表由开关是否导通决定。","en":"Two switches in series give AND, in parallel give OR, and a normally-closed one gives NOT."},"source":"../computing/systems/switches-that-compute/#ch1","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch1","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["逻辑门","与门 或门 非门","真值表","继电器","晶体管怎么做运算","布尔代数","布尔逻辑"],"en":["logic gate","AND OR NOT","truth table","relay logic","how transistors compute","boolean algebra","logic gates","boolean logic"]}},
"nand-universality":{"description":{"zh":"非、与、或、异或都能只用与非门拼出，最少分别要 1、2、3、4 个。","en":"NOT, AND, OR and XOR can all be built from NAND alone, with at least 1, 2, 3 and 4 gates."},"source":"../computing/systems/switches-that-compute/#ch2","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch2","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["与非门","NAND","通用门","为什么只用一种门","异或门怎么做"],"en":["NAND gate","universal gate","functional completeness","build XOR from NAND"]}},
"binary-numbers":{"description":{"zh":"n 个开关有 2ⁿ 种样子，8 个开关表示 0 到 255，255 加 1 绕回 0。","en":"n switches have 2ⁿ patterns; 8 of them hold 0 to 255, and 255 + 1 wraps to 0."},"source":"../computing/systems/switches-that-compute/#ch3","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch3","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["二进制","比特 字节","为什么是 256","满二进一","8 位能表示多少"],"en":["binary","bits and bytes","why 256","base 2","how many values in 8 bits","binary numbers"]}},
"ripple-carry-adder":{"description":{"zh":"半加器、全加器排成行波进位加法器；进位每多走一列多等约 4 个门延迟，最坏 32 个。","en":"Half and full adders chained into a ripple-carry adder; each column of carry adds about 4 gate delays, 32 at worst."},"source":"../computing/systems/switches-that-compute/#ch4","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch4","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["加法器","半加器","全加器","进位","计算机怎么做加法","关键路径","门延迟"],"en":["adder","half adder","full adder","carry propagation","how computers add","critical path","gate delay","how a computer adds numbers"]}},
"twos-complement-overflow":{"description":{"zh":"减法 = 加上取反再加 1，同一个加法器多一根线就会减；越过 127 与 −128 的缝就是溢出。","en":"Subtracting is adding the inverted number plus one; crossing the 127/−128 seam is overflow."},"source":"../computing/systems/switches-that-compute/#ch5","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch5","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["补码","计算机怎么表示负数","溢出","减法器","整数溢出","有符号 无符号","负数在计算机里怎么存"],"en":["two's complement","negative numbers in binary","integer overflow","signed vs unsigned","subtractor"]}},
"latch-metastability":{"description":{"zh":"两个与非门首尾相接就能记住一位；S、R 同时松开时会振荡或随机落到一边。","en":"Two cross-coupled NANDs remember a bit; releasing S and R together makes it oscillate or fall either way."},"source":"../computing/systems/switches-that-compute/#ch6","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch6","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["锁存器","SR 锁存器","电路怎么记忆","亚稳态","内存怎么存一位","计算机怎么记住一位"],"en":["latch","SR latch","how circuits remember","metastability","how memory stores a bit","flip-flop","flip-flop memory"]}},
"clock-counter":{"description":{"zh":"寄存器加上加法器和时钟就是计数器；时钟周期短于最长路径时会收下错误的值。","en":"A register plus an adder and a clock makes a counter; a clock shorter than the longest path latches wrong values."},"source":"../computing/systems/switches-that-compute/#ch7","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch7","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["时钟","触发器","寄存器","计数器","主频为什么有上限","CPU 频率"],"en":["clock","flip-flop","register","counter","why clock speed is limited","CPU frequency"]}},
"mux-alu":{"description":{"zh":"控制线挑选答案；比较两个数就是相减再看 Z 和 C 标志。","en":"Control lines pick an answer; comparing two numbers is subtracting and reading the Z and C flags."},"source":"../computing/systems/switches-that-compute/#ch8","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch8","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["多路选择器","ALU","算术逻辑单元","计算机怎么比较大小","标志位"],"en":["multiplexer","ALU","arithmetic logic unit","how computers compare","flags"]}},
"stored-program-machine":{"description":{"zh":"一台 16 字节、7 条指令的机器，用重复加法做乘法；指令也只是内存里的数。","en":"A 16-byte, 7-instruction machine multiplies by repeated addition; instructions are just numbers in memory."},"source":"../computing/systems/switches-that-compute/#ch9","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch9","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["CPU 怎么执行程序","程序计数器","取指 译码 执行","冯·诺依曼结构","机器码","指令集","计算机怎么执行指令"],"en":["how a CPU runs a program","program counter","fetch decode execute","von Neumann architecture","machine code","instruction set"]}},
"floating-point-rounding":{"description":{"zh":"0.1 在二进制里写不完，存进有限的尾数要取整，所以 0.1 + 0.2 得到 0.30000000000000004。","en":"0.1 never ends in binary, so it is rounded into a finite mantissa and 0.1 + 0.2 becomes 0.30000000000000004."},"source":"../computing/systems/switches-that-compute/#ch10","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch10","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["0.1+0.2","0.1 + 0.2 不等于 0.3","浮点数","浮点误差","精度丢失","double float 区别"],"en":["0.1 + 0.2","floating point error","why 0.1+0.2 != 0.3","IEEE 754","double vs float","rounding error"]}},
"real-processor-scale":{"description":{"zh":"流水线、先行进位、缓存和多核都是同样零件的更多份；附 2038 年问题等可带走的结论。","en":"Pipelining, carry-lookahead, caches and many cores are more of the same parts; with takeaways like the year-2038 problem."},"source":"../computing/systems/switches-that-compute/#ch11","lessons":[{"slug":"switches-that-compute","step":null,"anchor":"ch11","category":"computing","stage":"senior","primary":true}],"aliases":{"zh":["流水线","缓存","芯片有多少晶体管","2038 年问题","CPU 和我们搭的有什么区别","指令流水线","CPU 流水线"],"en":["pipelining","cache","transistor count","year 2038 problem","how real CPUs differ","instruction pipeline"]}},
"big-o-notation":{"description":{"zh":"大 O 只说算法的工作量随输入规模 n 怎样增长，去掉了常数系数：O(n²) 的算法 n 翻倍时工作量约翻 4 倍，O(n log n) 只约翻 2 倍多；系数仍然存在，所以 n 小时“形状差”的算法也可能更快，但 n 足够大时形状一定胜出。","en":"Big O describes only how an algorithm’s work grows with the input size n, dropping constant factors: doubling n roughly quadruples the work of an O(n²) algorithm but only slightly more than doubles an O(n log n) one; the constants are still real, so for small n a worse-shaped algorithm can win, but for large enough n the shape always decides."},"formula":"O(n²) vs O(n log n)","source":"../computing/algorithms/sorting/#step4","lessons":[{"slug":"sorting","step":4,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["大 O 表示法","时间复杂度","复杂度分析","O(n log n)","O(n²) 是什么意思","算法效率","渐近复杂度","big o"],"en":["Big O notation","time complexity","complexity analysis","n log n","what does O(n squared) mean","algorithm efficiency","asymptotic complexity","big-oh"]}},
"binary-search":{"description":{"zh":"在有序表里找数：先看中间，目标小了往左半找、大了往右半找，每步砍掉一半。n 个数最多约 log₂n 步；无序就没法砍半，只能一个个看。","en":"Finding a number in a sorted list: look at the middle, go left if the target is smaller, right if bigger, cutting half away each step. n items take about log₂n steps at most; unsorted, halving is impossible and you can only scan one by one."},"formula":"steps ≈ log₂n","source":"../computing/algorithms/binary-search/#step0","lessons":[{"slug":"binary-search","step":0,"category":"computing","stage":"university","primary":true}]},
"cnn-feature-maps":{"description":{"zh":"3×3 卷积核在图像上滑动，对应相乘求和得到特征图；不同的核响应不同的边缘，ReLU、池化与堆叠把边缘拼成更复杂的特征，核也可以由梯度下降学出。合成小图、单通道的教学模型。","en":"A 3×3 kernel slides over an image, multiplying and summing to give a feature map; different kernels respond to different edges, ReLU, pooling and stacking assemble edges into richer features, and kernels can be learned by gradient descent. A teaching model with small synthetic images and one channel."},"formula":"out(i,j) = Σₐ Σ_b k(a,b)·x(i+a, j+b)","source":"../computing/ml/cnn-feature-maps/#step0","lessons":[{"slug":"cnn-feature-maps","step":0,"category":"computing","stage":"university","primary":true}],"note":"No machine-learning group in the atlas; group left OTHER. Edge to the atlas node convolution is real: a 2-D kernel is the same flip-free sliding weighted sum.","aliases":{"zh":["卷积神经网络"],"en":["convolutional neural network","CNN"]}},
"graph-algorithms":{"description":{"zh":"把问题画成点和边，再按规则走：点是地点或状态，边是连接、权重是代价。最短路、PageRank、遍历都是同一套画法换不同规则：每次确认什么、按什么顺序展开，决定了算出什么。","en":"Draw a problem as vertices and edges, then walk by a rule: vertices are places or states, edges are links, weights are costs. Shortest paths, PageRank and traversals are the same drawing with different rules — what you settle each time, and in what order, decides what you compute."},"source":"../computing/algorithms/graph-algorithms/#step1","lessons":[{"slug":"graph-algorithms","step":1,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["图论"],"en":["graph theory"]}},
"graphics-pipeline":{"description":{"zh":"屏幕上的画面按三层流水做出来：先用矩阵把顶点旋转、缩放到屏幕坐标，再把连续的线段和三角形离散成一个个像素（光栅化），最后按表面法线和光线方向的点积算出每个像素的亮度。","en":"An on-screen image is made in three stages: matrices first rotate and scale the vertices into screen coordinates, then continuous lines and triangles are turned into individual pixels (rasterisation), and finally each pixel’s brightness comes from the dot product of the surface normal with the light direction."},"formula":"brightness = albedo · max(0, n·ℓ)","source":"../computing/graphics/computer-graphics/#step0","lessons":[{"slug":"computer-graphics","step":0,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["计算机图形学","渲染管线","光栅化","漫反射着色","Lambert 光照","画线算法","游戏画面是怎么画出来的","GPU 渲染"],"en":["computer graphics","rendering pipeline","rasterization","diffuse shading","Lambertian shading","line drawing algorithm","how do games draw images","GPU rendering"]}},
"hashing":{"description":{"zh":"把任意长的数据压成固定长的指纹：同一个输入永远得到同一串输出，输出改一位、输入面目全非也看不出规律。反过来从指纹倒推原文不可行——这就是单向：正向便宜、反向昂贵，RSA 的锁芯也是同一思想。","en":"Squeezing any-length data into a fixed-length fingerprint: the same input always gives the same output, and changing one output bit reveals nothing about the input. Reversing a fingerprint back to the original is infeasible — that is one-way: cheap forward, expensive backward, the same idea as RSA's lock."},"formula":"h: {0,1}* → {0,1}^n","source":"../computing/algorithms/hashing/#step0","lessons":[{"slug":"hashing","step":0,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["哈希表","哈希函数","散列"],"en":["hash function","hash table","hash map"]}},
"kv-cache-vs-fixed-state":{"description":{"zh":"全注意力层按上下文长度 O(L) 保存键值缓存，而线性循环层把历史压进 O(1) 状态矩阵。","en":"Full-attention layers store O(L) keys and values while linear layers keep a constant O(1) state matrix."},"source":"../computing/ml/how-hybrid-attention-remembers/#ch1","lessons":[{"slug":"how-hybrid-attention-remembers","step":null,"anchor":"ch1","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["KV Cache","为什么长上下文占内存","显存爆炸","混合注意力","Qwen3.5 为什么省内存"],"en":["KV cache memory","why long context uses RAM","hybrid attention memory","O(1) state"]}},
"latency-bandwidth":{"description":{"zh":"传一份数据的时间约等于往返延迟加上数据量 ÷ 带宽：延迟像水要走多远，带宽像水管多粗；短消息主要被延迟拖慢，大文件才主要受带宽限制，所以加宽水管救不了“卡顿”。","en":"Sending some data takes roughly the round-trip latency plus size ÷ bandwidth: latency is how far the water has to travel, bandwidth how wide the pipe is; short messages are slowed mainly by latency and only large files mainly by bandwidth, so a wider pipe does not cure lag."},"formula":"t ≈ RTT + size / bandwidth","source":"../computing/systems/tcp-congestion/#step1","lessons":[{"slug":"tcp-congestion","step":1,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["网络延迟","带宽","网速慢","ping 值","往返时间 RTT","网速和延迟的区别","数据包","吞吐量"],"en":["network latency","bandwidth","slow internet","ping","round-trip time","bandwidth vs latency","packets","throughput"]}},
"pipeline-memory-stall":{"description":{"zh":"五级流水线每拍完成一条指令，但一旦遇到等内存的数据相关，后续指令只能停顿吐气泡。","en":"A 5-stage pipeline retires one instruction per cycle until a memory-latency hazard fills the pipe with stall bubbles."},"source":"../computing/systems/why-compute-waits-for-memory/#ch1","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch1","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["流水线气泡","CPU 为什么会等内存","取指 译码 执行","数据旁路","CPI","AI 芯片为什么大部分时间都在等"],"en":["pipeline stall","instruction pipeline","load-use hazard","forwarding","why does an AI chip wait","why compute waits for memory"]}},
"quorum-replication":{"description":{"zh":"把同一份数据存 N 份，写入要等 W 个副本确认，读取要问 R 个副本；当 R + W > N 时读和写问到的副本必有重叠，能读到最新值；可网络一断开，能回应的副本变少，“总能回答”和“答的一定最新”就很难兼得。","en":"Store the same data N times; a write waits for W replicas to confirm and a read asks R of them; when R + W > N the read and write sets must overlap, so the newest value can be found — but when the network splits, fewer replicas can answer, and “always answers” and “always up to date” become hard to have together."},"formula":"R + W > N","source":"../computing/systems/distributed-systems/#step0","lessons":[{"slug":"distributed-systems","step":0,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["分布式系统","数据副本","法定人数 quorum","R + W > N","CAP 定理","强一致性 最终一致性","网络分区","为什么会读到旧数据"],"en":["distributed systems","data replication","quorum","R plus W greater than N","CAP theorem","strong vs eventual consistency","network partition","why do I read stale data"]}},
"robot-kinematics":{"description":{"zh":"二连杆机械臂的末端位置是两段连杆向量之和：给定两个关节角就能算出手在哪（正运动学）；反过来给定目标点求关节角（逆运动学）通常有“肘上、肘下”两组解；两杆伸直共线时，某些方向怎么转关节都动不了，叫奇异位形。","en":"The tip of a two-link arm is the sum of two link vectors: given the two joint angles you can compute where the hand is (forward kinematics); going back from a target point to joint angles (inverse kinematics) usually has two answers, elbow-up and elbow-down; when the links line up straight, some directions cannot be reached by any joint motion — a singular configuration."},"formula":"x = l₁cosθ₁ + l₂cos(θ₁+θ₂)","source":"../computing/graphics/robot-kinematics/#step0","lessons":[{"slug":"robot-kinematics","step":0,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["正运动学","逆运动学","机械臂","雅可比矩阵","奇异位形","二连杆","工作空间","机器人学入门","机器人运动学"],"en":["forward kinematics","inverse kinematics","robot arm","Jacobian matrix","singularity","two-link arm","workspace","introduction to robotics","robot kinematics"]}},
"sorting-algorithms":{"description":{"zh":"同样把一堆数排好，冒泡排序靠相邻两两交换、要比较约 n² 次；归并排序把数组对半切开、分别排好再像拉链一样合并，只需约 n log₂ n 次——差距不在写得勤快，而在比较次数随数据量增长的形状。","en":"Both get a list in order, but bubble sort swaps neighbours and needs about n² comparisons, while merge sort halves the list, sorts each half and zips them together in about n log₂ n — the difference is not effort but how the comparison count grows with the amount of data."},"source":"../computing/algorithms/sorting/#step2","lessons":[{"slug":"sorting","step":2,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["排序算法","冒泡排序","归并排序","快速排序","选择排序","计数排序","哪种排序最快","sort 算法"],"en":["sorting algorithm","bubble sort","merge sort","quicksort","selection sort","counting sort","which sorting algorithm is fastest","sorting algorithms"]}},
"tcp-congestion-control":{"description":{"zh":"发送端不知道网络还能承受多少，就用拥塞窗口一点点试：每收到确认就多发一点，一旦超时或丢包就大幅退让；网络的稳定吞吐就是这个“加一点、砍一刀”的闭环维持出来的。","en":"A sender cannot know how much the network can take, so it probes with a congestion window: each acknowledgement lets it send a little more, and a timeout or lost packet makes it back off sharply; steady network throughput is held by this add-a-little, cut-hard loop."},"source":"../computing/systems/tcp-congestion/#step4","lessons":[{"slug":"tcp-congestion","step":4,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["拥塞控制","拥塞窗口","TCP 三次握手","丢包重传","慢启动","加性增乘性减","网络为什么会堵","TCP 和 IP"],"en":["congestion control","congestion window","TCP three-way handshake","packet loss and retransmission","slow start","AIMD","why does the network get congested","TCP/IP"]}},
"linear-attention-associativity":{"description":{"zh":"去掉 Softmax 后可将 (QK^T)V 改写为 Q(K^TV)，把 O(L^2 d) 化为 O(Ld^2) 状态累加。","en":"Dropping softmax lets (QK^T)V regroup into Q(K^TV), turning O(L^2 d) into O(Ld^2) state accumulation."},"source":"../computing/ml/how-hybrid-attention-remembers/#ch2","lessons":[{"slug":"how-hybrid-attention-remembers","step":null,"anchor":"ch2","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["线性注意力","矩阵结合律","O(L^2) 到 O(L)","Linear Attention"],"en":["linear attention","matrix associativity","subquadratic attention"]}},
"memory-hierarchy-cache-walk":{"description":{"zh":"从 L1 到 DRAM 慢了约 80 倍；因为硬件按缓存行搬运，按行遍历与按列遍历矩阵的流量可差 8 倍。","en":"DRAM is roughly 80x slower than L1 cache; because hardware fetches full cache lines, row-major vs column-major matrix walks can differ by 8x in traffic."},"source":"../computing/systems/why-compute-waits-for-memory/#ch2","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch2","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["缓存命中率","L1 L2 L3 缓存","按行遍历 按列遍历","空间局部性","缓存行","组相联缓存","为什么二维数组按行更快"],"en":["cache hierarchy","L1 L2 L3 DRAM latency","row major vs column major","spatial locality","cache line","set associative cache"]}},
"cache-tiling-blocking":{"description":{"zh":"同样做 2N³ 次乘加的矩阵乘法，把小块锁进缓存能减少近十倍慢内存搬运，分块过大溢出缓存又会恶化。","en":"Matrix multiplication does the same 2N^3 ops, yet cache-sized tiling cuts slow memory traffic nearly 10x while oversized tiles thrash capacity."},"source":"../computing/systems/why-compute-waits-for-memory/#ch3","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch3","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["矩阵乘法分块","tiling","blocking","时间局部性","缓存颠簸","为什么同样 O(N^3) 速度差十倍"],"en":["matrix multiply tiling","loop blocking","temporal locality","cache thrashing","IO complexity"]}},
"fast-weight-capacity":{"description":{"zh":"d×d 状态矩阵最多无串扰容纳 d 个正交键，超载或改写旧键时纯加法会把新旧值糊在一起。","en":"A d x d matrix holds at most d orthogonal keys without interference; pure addition blurs overwritten keys."},"source":"../computing/ml/how-hybrid-attention-remembers/#ch3","lessons":[{"slug":"how-hybrid-attention-remembers","step":null,"anchor":"ch3","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["快权重","Fast Weight Programmer","正交容量上限","线性注意力为什么健忘"],"en":["fast weights","orthogonal capacity","why linear attention forgets"]}},
"delta-rule-memory-update":{"description":{"zh":"先读取 S_{t-1}k_t 再写回残差 (v_t - S_{t-1}k_t)，沿键方向精准抹除旧值并改写。","en":"Read S_{t-1}k_t first and write back only the residual, erasing old values along k_t before writing."},"source":"../computing/ml/how-hybrid-attention-remembers/#ch4","lessons":[{"slug":"how-hybrid-attention-remembers","step":null,"anchor":"ch4","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["DeltaNet","Delta 规则","Widrow-Hoff","先擦后写"],"en":["DeltaNet","delta rule","memory overwrite"]}},
"memory-wall-littles-law":{"description":{"zh":"哪怕只有 2% 的缓存缺失也会拉低一半以上有效算力；要吃满高速总线，在途并发数据必须等于带宽乘延迟。","en":"Even a 2% miss rate cuts effective compute more than half; saturating a fast memory bus requires concurrency equal to bandwidth times latency."},"source":"../computing/systems/why-compute-waits-for-memory/#ch4","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch4","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["内存墙","memory wall","利特尔法则","AMAT","延迟与带宽的区别","隐藏内存延迟"],"en":["memory wall","Little's Law","AMAT","latency vs bandwidth","latency hiding","in-flight memory requests"]}},
"amdahl-gustafson-bus-cap":{"description":{"zh":"登纳德缩放结束后靠多核扩展，但串行比例（阿姆达尔定律）和共享内存总线很快把加速比封顶。","en":"After Dennard scaling ended, more cores hit serial bottlenecks (Amdahl's law) and shared memory bus saturation."},"source":"../computing/systems/why-compute-waits-for-memory/#ch5","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch5","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["阿姆达尔定律","古斯塔夫森定律","为什么多核不能线性加速","登纳德缩放","内存带宽瓶颈"],"en":["Amdahl's law","Gustafson's law","Dennard scaling","why more cores don't scale","shared memory bus bottleneck"]}},
"gated-deltanet-forgetting":{"description":{"zh":"将 Mamba-2 的全局衰减门 α_t 与 Delta 投影擦除结合，既清扫过时话题又精准改写当前键。","en":"Combines Mamba-2 global decay α_t with delta erasure to clear stale topics and update active keys."},"source":"../computing/ml/how-hybrid-attention-remembers/#ch5","lessons":[{"slug":"how-hybrid-attention-remembers","step":null,"anchor":"ch5","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["Gated DeltaNet","Mamba-2 衰减门","遗忘门","qwen35 架构"],"en":["Gated DeltaNet","Mamba-2 gating","selective decay"]}},
"chunkwise-ssd-parallelism":{"description":{"zh":"把序列切块后块内化为 C×C 矩阵乘法喂给张量核，只串行传递块边界状态，串行深度缩小 C 倍。","en":"Partitioning into chunks turns intra-chunk work into C x C tensor-core matmuls and cuts serial depth by C."},"source":"../computing/ml/how-hybrid-attention-remembers/#ch6","lessons":[{"slug":"how-hybrid-attention-remembers","step":null,"anchor":"ch6","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["SSD 对偶","分块并行","Chunkwise","Mamba 怎么并行训练"],"en":["structured state space duality","chunkwise parallel","SSD Mamba-2"]}},
"gpu-systolic-array":{"description":{"zh":"GPU/TPU 用大量并发线程掩盖延迟，并通过脉动阵列让权重驻留片上反复复用。","en":"GPUs and TPUs trade per-thread latency for massive warp concurrency and systolic arrays that reuse weights on-chip."},"source":"../computing/systems/why-compute-waits-for-memory/#ch6","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch6","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["脉动阵列","为什么 AI 用 GPU 不用 CPU","TPU 原理","张量核","CPU 和 GPU 区别","吞吐量优先"],"en":["systolic array","why GPUs for AI","TPU architecture","tensor core","CPU vs GPU","throughput vs latency"]}},
"hybrid-ratio-exact-recall":{"description":{"zh":"保留 1/4 全注意力层作无损书签，既解决纯线性在超长文档大海捞针时的崩塌，又省下 75% KV。","en":"Keeping 25% full-attention layers preserves exact needle-in-a-haystack lookup while saving 75% KV cache."},"source":"../computing/ml/how-hybrid-attention-remembers/#ch7","lessons":[{"slug":"how-hybrid-attention-remembers","step":null,"anchor":"ch7","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["3:1 混合","大海捞针","Needle in a Haystack","为什么不纯用线性注意力"],"en":["3:1 hybrid ratio","needle in a haystack","why hybrid attention"]}},
"roofline-model":{"description":{"zh":"可达性能等于峰值算力与（带宽 × 算术强度）中的较小者；算术强度越过屋脊拐点才算吃满算力。","en":"Attainable performance is min(peak FLOP/s, bandwidth x arithmetic intensity); only past the ridge point is a workload compute-bound."},"source":"../computing/systems/why-compute-waits-for-memory/#ch7","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch7","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["屋顶线模型","roofline","算术强度","FLOP/byte","内存受限 算力受限","屋脊拐点"],"en":["roofline model","arithmetic intensity","memory bound vs compute bound","ridge point","FLOP per byte"]}},
"hybrid-decode-roofline":{"description":{"zh":"生成阶段受限于内存带宽，每省下 1 GB KV 流量就直接换来长上下文下的本地吐字提速。","en":"Because decode is memory-bandwidth bound, shrinking KV reads directly accelerates long-context generation."},"source":"../computing/ml/how-hybrid-attention-remembers/#ch8","lessons":[{"slug":"how-hybrid-attention-remembers","step":null,"anchor":"ch8","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["屋顶线","本地大模型吐字速度","Bandwidth bound","为什么混合模型跑得快"],"en":["decode roofline","local LLM throughput","memory bandwidth bound decode"]}},
"llm-inference-memory-bound":{"description":{"zh":"自回归解码每吐一个字就要读取全部权重与 KV 缓存，单批算术强度约 1 FLOP/B；量化与批处理用于提高重用。","en":"Autoregressive LLM decode reads all weights and KV cache per token (~1 FLOP/B at batch 1); quantization and batching shift the bottleneck."},"source":"../computing/systems/why-compute-waits-for-memory/#ch8","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch8","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["大模型推理为什么慢","为什么推理吃显存带宽","KV 缓存","批量推理","权重量化","预填充与解码"],"en":["why LLM inference is slow","memory-bound LLM decode","prefill vs decode","KV cache bandwidth","batching and quantization"]}},
"data-movement-energy-hbm":{"description":{"zh":"从片外 DRAM 读取数据的能耗是浮点加法的几百倍；HBM 靠极短极宽的硅中介层连线降低距离与能耗。","en":"Fetching a word from off-chip DRAM costs hundreds of times more energy than adding it; HBM stacks dies on a wide interposer to shorten wires."},"source":"../computing/systems/why-compute-waits-for-memory/#ch9","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch9","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["HBM 高带宽内存","数据搬运能耗","Horowitz 能耗","为什么 HBM 这么贵","CoWoS","NVLink 带宽"],"en":["HBM high bandwidth memory","data movement energy","Horowitz energy table","why HBM matters","NVLink vs PCIe"]}},
"hybrid-attention-frontier-2026":{"description":{"zh":"对比纯全注意力、3:1 混合、7:1 混合与纯线性模型在内存、吞吐与召回上的工程取舍。","en":"Compares pure full, 3:1 hybrid, 7:1 hybrid, and pure linear layouts across RAM, throughput, and recall."},"source":"../computing/ml/how-hybrid-attention-remembers/#ch9","lessons":[{"slug":"how-hybrid-attention-remembers","step":null,"anchor":"ch9","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["MiniMax-01","Kimi Linear","Qwen3.5","混合模型对比"],"en":["MiniMax-01","Kimi Linear","Qwen3.5 hybrid","KDA"]}},
"memory-wall-frontier-2026":{"description":{"zh":"2026 年末 AI 芯片迈向 2048-bit HBM4 与共封装光学，同时 PIM 与神经形态硬件仍在与生态和成本博弈。","en":"Late-2026 hardware pushes toward 2048-bit HBM4 and co-packaged optics while PIM and neuromorphic chips face area and software hurdles."},"source":"../computing/systems/why-compute-waits-for-memory/#ch10","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch10","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["HBM4","HBM3e","B200 H100 对比","Rubin","共封装光学 CPO","CXL 内存池","存算一体 PIM"],"en":["HBM4","HBM3e","Blackwell B200 bandwidth","co-packaged optics","CXL memory pooling","processing in memory PIM"]}},
"memory-diagnostic-checklist":{"description":{"zh":"用步长局部性、算术强度、在途并发和芯片外边界四个问题快速定位性能瓶颈。","en":"Locate performance bottlenecks using four checks: stride locality, arithmetic intensity, in-flight concurrency, and off-chip boundaries."},"source":"../computing/systems/why-compute-waits-for-memory/#ch11","lessons":[{"slug":"why-compute-waits-for-memory","step":null,"anchor":"ch11","category":"computing","stage":"university","primary":true}],"aliases":{"zh":["怎么看 AI 芯片参数","怎么排查程序慢","性能瓶颈诊断"],"en":["how to read GPU specs","performance checklist","memory bottleneck diagnosis"]}}
}});
